package com.aoo.bcg.common.invite;
import java.time.Instant;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class InviteRevocationRegistryTest{@Test void lifecycleAndPermissionChangesInvalidateImmediately(){Instant future=Instant.now().plusSeconds(60);var registry=new InviteRevocationRegistry();registry.register("room-end",1,10,100,future);registry.register("template",2,20,200,future);registry.register("inviter",3,30,300,future);registry.roomEnded(1);registry.templateDeleted(20);registry.inviterPermissionRevoked(300);assertFalse(registry.active("room-end",Instant.now()));assertFalse(registry.active("template",Instant.now()));assertFalse(registry.active("inviter",Instant.now()));assertEquals(InviteRevocationRegistry.Reason.ROOM_ENDED,registry.snapshot().get("room-end").revokedReason());}}
